import re
from jsonschema import validate, ValidationError

# 1. exact match — classification, closed categories
def grader_exact_match(obtained, expected):
    return obtained.strip().lower() == expected.strip().lower()

# 2. regular expression — free format but with a required pattern
def grader_regex(text, pattern=r"^\[(shipping|refund|defective_product)\]"):
    return bool(re.match(pattern, text))

# 3. schema validation — structured outputs (JSON / tool use)
def grader_schema(json_data, schema):
    try:
        validate(instance=json_data, schema=schema)
        return True
    except ValidationError:
        return False

hits = sum(1 for r in results if grader_exact_match(r["obtained"], r["expected"]))
accuracy = hits / len(results)
print(f"Accuracy: {accuracy:.1%}")

import ast
import json
import re

# 4. syntax validation — the output IS code, not data describing something
def validate_json(text):
    try:
        json.loads(text.strip())
        return 10
    except json.JSONDecodeError:
        return 0

def validate_python(text):
    try:
        ast.parse(text.strip())
        return 10
    except SyntaxError:
        return 0

def validate_regex(text):
    try:
        re.compile(text.strip())
        return 10
    except re.error:
        return 0

def grade_syntax(output, test_case):
    validator = {"json": validate_json, "python": validate_python, "regex": validate_regex}
    return validator[test_case["format"]](output)

