import random

def stratified_sampling(extractions: list[dict], min_per_stratum: int = 15) -> list[dict]:
    strata: dict[tuple, list[dict]] = {}
    for ext in extractions:
        key = (ext["document_type"], ext["confidence_bucket"])  # e.g.: ("invoice", "low")
        strata.setdefault(key, []).append(ext)

    sample = []
    for key, items in strata.items():
        n = min(min_per_stratum, len(items))
        sample.extend(random.sample(items, n))
    return sample  # every stratum is represented, regardless of its original size

