def calibrate_threshold(validation_set: list[dict]) -> dict:
    # validation_set: [{"confidence": 0.92, "correct": True}, ...] with human ground truth
    buckets = {}
    for item in validation_set:
        bucket = round(item["confidence"], 1)
        buckets.setdefault(bucket, []).append(item["correct"])

    calibration = {
        bucket: sum(hits) / len(hits)
        for bucket, hits in buckets.items()
    }
    # if confidence=0.9 corresponds to a real accuracy of 0.65, the model is
    # overconfident in that range: the auto-approval threshold should be raised
    return calibration
